solution:
class TaskManager:
    def __init__(self):
        self._tasks = []
        self._next_id = 1

    def add_task(self, title, priority):
        task = {'id': self._next_id, 'title': title, 'priority': priority, 'done': False}
        self._tasks.append(task)
        self._next_id += 1
        return task

    def complete_task(self, task_id):
        for task in self._tasks:
            if task['id'] == task_id:
                task['done'] = True
                return True
        return False

    def get_pending(self):
        return sorted([t for t in self._tasks if not t['done']], key=lambda t: t['priority'])

    def get_by_priority(self, priority):
        return [t for t in self._tasks if t['priority'] == priority]

    def summary(self):
        done = sum(1 for t in self._tasks if t['done'])
        return {'total': len(self._tasks), 'done': done, 'pending': len(self._tasks) - done}
